/* campage.c - the camera web page (0.104): GET /camera. Preview from /api/camera.jpg, settings with
 * sliders via POST /api/camera. API access: the browser login (users) or the token, kept in localStorage. */
const char camera_page[] =
"<!doctype html><html><head><meta charset=\"utf-8\"><title>RoboOS camera</title>"
"<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">"
"<style>"
"body{font-family:system-ui,sans-serif;background:#101418;color:#d0d0d0;margin:0;padding:12px}"
"h1{color:#55ffff;font-size:1.3em;margin:0 0 8px}"
"#wrap{display:flex;flex-wrap:wrap;gap:16px}"
"#pv{flex:1 1 480px;max-width:900px}"
"#pv img{width:100%;background:#000;border:1px solid #333;aspect-ratio:4/3;display:block}"
"#side{flex:1 1 300px;max-width:420px}"
".row{display:grid;grid-template-columns:90px 1fr 56px;align-items:center;gap:6px;margin:6px 0}"
".row input[type=range]{width:100%}"
".v{text-align:right;font-family:monospace}"
"button,select{background:#24303a;color:#e0e0e0;border:1px solid #456;border-radius:4px;padding:6px 10px;font-size:1em}"
"button:hover{background:#2f3f4c}"
"#st,#msg{font-family:monospace;font-size:.9em;margin:6px 0;color:#9ab}"
"#msg{color:#ffb060}"
"#tok{display:none;margin:8px 0}#tok input{width:60%}"
"label{user-select:none}"
"</style></head><body>"
"<h1>RoboOS camera</h1>"
"<div id=\"tok\">API token: <input id=\"tk\" type=\"password\"> <button onclick=\"setTok()\">OK</button></div>"
"<div id=\"wrap\"><div id=\"pv\"><img id=\"im\" alt=\"\">"
"<div><label><input type=\"checkbox\" id=\"live\" checked> live</label> "
"<button onclick=\"snap()\">Save photo</button> "
"<a id=\"dl\" download=\"camera.jpg\" style=\"color:#8cf\">download this picture</a></div>"
"<div id=\"st\"></div><div id=\"msg\"></div></div>"
"<div id=\"side\">"
"<div class=\"row\"><span>exposure</span><input type=\"range\" id=\"exposure\" min=\"1\" max=\"356\" step=\"1\"><span class=\"v\" id=\"exposure_v\"></span></div>"
"<div class=\"row\"><span></span><label><input type=\"checkbox\" id=\"exposure_a\"> auto</label><span></span></div>"
"<div class=\"row\"><span>gain</span><input type=\"range\" id=\"gain\" min=\"10\" max=\"159\" step=\"1\"><span class=\"v\" id=\"gain_v\"></span></div>"
"<div class=\"row\"><span></span><label><input type=\"checkbox\" id=\"gain_a\"> auto</label><span></span></div>"
"<div class=\"row\"><span>EV (auto)</span><input type=\"range\" id=\"ev\" min=\"-3\" max=\"3\" step=\"1\"><span class=\"v\" id=\"ev_v\"></span></div>"
"<div class=\"row\"><span>white bal.</span><select id=\"wb\"><option value=\"auto\">auto</option><option value=\"lock\">lock</option><option value=\"manual\">manual</option></select><span></span></div>"
"<div class=\"row\"><span>red</span><input type=\"range\" id=\"wb_r\" min=\"10\" max=\"400\" step=\"1\"><span class=\"v\" id=\"wb_r_v\"></span></div>"
"<div class=\"row\"><span>blue</span><input type=\"range\" id=\"wb_b\" min=\"10\" max=\"400\" step=\"1\"><span class=\"v\" id=\"wb_b_v\"></span></div>"
"<div class=\"row\"><span>brightness</span><input type=\"range\" id=\"brightness\" min=\"-100\" max=\"100\"><span class=\"v\" id=\"brightness_v\"></span></div>"
"<div class=\"row\"><span>contrast</span><input type=\"range\" id=\"contrast\" min=\"-100\" max=\"100\"><span class=\"v\" id=\"contrast_v\"></span></div>"
"<div class=\"row\"><span>saturation</span><input type=\"range\" id=\"saturation\" min=\"0\" max=\"300\"><span class=\"v\" id=\"saturation_v\"></span></div>"
"<div class=\"row\"><span>hue</span><input type=\"range\" id=\"hue\" min=\"-180\" max=\"180\"><span class=\"v\" id=\"hue_v\"></span></div>"
"<div class=\"row\"><span>sharpness</span><input type=\"range\" id=\"sharpness\" min=\"0\" max=\"200\"><span class=\"v\" id=\"sharpness_v\"></span></div>"
"<div class=\"row\"><span>lamp flicker</span><select id=\"flicker\"><option value=\"50\">50 Hz (Europe)</option><option value=\"60\">60 Hz</option><option value=\"off\">off</option></select><span></span></div>"
"<div class=\"row\"><span>JPEG quality</span><input type=\"range\" id=\"quality\" min=\"10\" max=\"100\"><span class=\"v\" id=\"quality_v\"></span></div>"
"<div class=\"row\"><span>gamma</span><label><input type=\"checkbox\" id=\"gamma\"> on</label><span></span></div>"
"<div class=\"row\"><span>flip</span><select id=\"flip\"><option value=\"off\">off</option><option value=\"h\">mirror</option><option value=\"v\">upside down</option><option value=\"hv\">both (turn 180)</option></select><span></span></div>"
"<div class=\"row\" id=\"irrow\"><span>IR light</span><select id=\"ir_mode\"><option value=\"off\">off</option><option value=\"on\">on</option><option value=\"photo\">while the camera runs</option><option value=\"auto\">auto (dark only)</option></select><span class=\"v\" id=\"ir_v\"></span></div>"
"<p><button onclick=\"post({defaults:'1'}).then(load)\">Defaults</button></p>"
"</div></div>"
"<script>\n"
"let tok=localStorage.getItem('roboos_token')||'',busy=0,shown=0,t0=Date.now();\n"
"const $=id=>document.getElementById(id);\n"
"function H(){return tok?{'Authorization':'Bearer '+tok}:{}}\n"
"function needTok(){$('tok').style.display='block';}\n"
"function setTok(){tok=$('tk').value.trim();localStorage.setItem('roboos_token',tok);$('tok').style.display='none';load();}\n"
"function msg(t){$('msg').textContent=t||'';}\n"
"async function post(o){const b={};for(const k in o)b[k]=String(o[k]);\n"
" const r=await fetch('/api/camera',{method:'POST',headers:Object.assign({'Content-Type':'application/json'},H()),body:JSON.stringify(b)});\n"
" if(r.status==401){needTok();throw 0;} const j=await r.json(); if(!j.ok)msg(j.error); else msg(''); return j;}\n"
"function lab(id){const e=$(id),v=$(id+'_v');if(!v)return;let x=+e.value;\n"
" v.textContent=id=='exposure'?(x/10).toFixed(1)+' ms':id=='gain'?(x/10).toFixed(1)+'x':id=='ev'?(x>0?'+':'')+x:(id=='wb_r'||id=='wb_b'||id=='saturation'||id=='sharpness')?x+'%':id=='hue'?x+'\\u00b0':x;}\n"
"function fill(j){for(const k of['ev','brightness','contrast','saturation','hue','quality','sharpness']){$(k).value=j[k];lab(k);}\n"
" $('exposure_a').checked=j.exposure=='auto';$('exposure').value=j.exposure=='auto'?Math.round(j.now_exposure_ms*10):Math.round(+j.exposure*10);lab('exposure');\n"
" $('gain_a').checked=j.gain=='auto';$('gain').value=j.gain=='auto'?Math.round(j.now_gain*10):Math.round(+j.gain*10);lab('gain');\n"
" $('wb').value=j.wb;$('wb_r').value=j.wb_r;$('wb_b').value=j.wb_b;lab('wb_r');lab('wb_b');\n"
" $('flicker').value=j.flicker?String(j.flicker):'off';$('gamma').checked=j.gamma;$('flip').value=j.flip;$('ir_mode').value=j.ir_mode;$('irrow').style.display=j.ir_pin?'grid':'none';}\n"
"function status(j){$('st').textContent=j.sensor+' '+j.width+'x'+j.height+' | exposure '+j.now_exposure_ms+' ms, gain '+j.now_gain+'x, white balance R '+j.wb_r+'% B '+j.wb_b+'%'+(j.last_photo?' | last photo '+j.last_photo:'');\n"
" if($('exposure_a').checked&&!busy){$('exposure').value=Math.round(j.now_exposure_ms*10);lab('exposure');}\n"
" if($('gain_a').checked&&!busy){$('gain').value=Math.round(j.now_gain*10);lab('gain');}\n"
" $('ir_v').textContent=j.ir_pin?(j.ir_on?'ON':'off'):'';\n"
" if($('wb').value!='manual'&&!busy){$('wb_r').value=j.wb_r;$('wb_b').value=j.wb_b;lab('wb_r');lab('wb_b');}}\n"
"async function load(){try{const r=await fetch('/api/camera',{headers:H()});if(r.status==401){needTok();return;}\n"
" const j=await r.json();if(!j.ok){msg(j.error);return;}fill(j);status(j);}catch(e){msg('no answer from the board');}}\n"
"async function poll(){try{const r=await fetch('/api/camera',{headers:H()});if(r.ok){const j=await r.json();if(j.ok)status(j);}}catch(e){}setTimeout(poll,2000);}\n"
"for(const k of['ev','brightness','contrast','saturation','hue','quality','sharpness']){$(k).oninput=()=>{busy=1;lab(k);};$(k).onchange=()=>{busy=0;post({[k]:$(k).value});};}\n"
"$('exposure').oninput=()=>{busy=1;lab('exposure');};$('exposure').onchange=()=>{busy=0;$('exposure_a').checked=false;post({exposure:($('exposure').value/10).toFixed(1)});};\n"
"$('exposure_a').onchange=()=>post({exposure:$('exposure_a').checked?'auto':($('exposure').value/10).toFixed(1)});\n"
"$('gain').oninput=()=>{busy=1;lab('gain');};$('gain').onchange=()=>{busy=0;$('gain_a').checked=false;post({gain:($('gain').value/10).toFixed(1)});};\n"
"$('gain_a').onchange=()=>post({gain:$('gain_a').checked?'auto':($('gain').value/10).toFixed(1)});\n"
"function wbm(){$('wb').value='manual';post({wb:$('wb_r').value+' '+$('wb_b').value});}\n"
"for(const k of['wb_r','wb_b']){$(k).oninput=()=>{busy=1;lab(k);};$(k).onchange=()=>{busy=0;wbm();};}\n"
"$('wb').onchange=()=>{const v=$('wb').value;if(v=='manual')wbm();else post({wb:v});};\n"
"$('gamma').onchange=()=>post({gamma:$('gamma').checked?'on':'off'});\n"
"$('flip').onchange=()=>post({flip:$('flip').value});\n"
"$('flicker').onchange=()=>post({flicker:$('flicker').value});\n"
"$('ir_mode').onchange=()=>post({ir_mode:$('ir_mode').value});\n"
"async function snap(){try{await post({snap:'1'});msg('saving on the card...');setTimeout(()=>msg(''),3000);}catch(e){}}\n"
"async function frame(){let wait=150;\n"
" if($('live').checked&&!document.hidden){try{const r=await fetch('/api/camera.jpg?'+Date.now(),{headers:H(),cache:'no-store'});\n"
"  if(r.ok){const b=await r.blob(),u=URL.createObjectURL(b),old=$('im').src;$('im').src=u;$('dl').href=u;if(old.startsWith('blob:'))setTimeout(()=>URL.revokeObjectURL(old),3000);shown++;}\n"
"  else if(r.status==401){needTok();wait=2000;} else {let e='';try{e=(await r.json()).error}catch(x){} msg('picture: '+(e||r.status));wait=2000;}}catch(e){wait=1000;}}\n"
" else wait=500; setTimeout(frame,wait);}\n"
"load();poll();frame();\n"
"</script></body></html>\n";
